class Solution {
public:
    string removeKdigits(string num, int k) {
        int n = num.size();
        int top = 0;
        for (int i = 0; i < n; i++) {
            while (k > 0 && top > 0 && num[top - 1] > num[i]) {
                top--;
                k--;
            }
            num[top++] = num[i];
        }
        top -= k;
        int start = 0;
        while (start < top && num[start] == '0') start++;
        if (start == top) return "0";
        return num.substr(start, top - start);
    }
};
